llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Tocotrienol, a chromanol with a polyprenyl side chain structurally analogous to the query's quinone-polyprenyl architecture, was reported to have poor oral bioavailability in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Lycopene, a highly lipophilic C40 isoprenoid, showed very low systemic availability in humans (0.17% of a 23.6 mg dose), and multiple lycopene studies report <3% systemic availability, supporting low F for large lipophilic isoprenoid-type molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, the closest Morgan analogue, showed 58.5% absolute bioavailability in humans, which would argue for high F if transferable; however, its lack of the polar quinone head and different absorption behavior reduce transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hyperforin, a lipophilic prenylated natural product, showed high oral bioavailability in volunteers, providing a weak contradictory signal, but its much lower structural similarity and smaller size limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is CoQ10, an extremely lipophilic polyprenyl quinone. The most relevant experimental evidence—tocotrienol poor oral bioavailability and lycopene low systemic availability—supports low F. Phytoene's high bioavailability is the closest analogue but is less transferable because it lacks the polar quinone head. Physicochemical liabilities (extreme logP, high MW, no ionizable groups) reinforce the low prediction.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for CoQ10 or a close quinone-polyprenyl analogue.",
    "Lycopene bioavailability estimates vary widely (0.17% to ~24%) depending on method and formulation, creating uncertainty in transferability.",
    "Formulation effects are not captured; some highly lipophilic compounds can be absorbed better with special formulations."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

